async function carregarPainel(api) {
  const [perfil, pedidos, avisos] = await Promise.allSettled([
    api.perfil(),
    api.pedidos(),
    api.avisos(),
  ]);

  return {
    perfil: perfil.status === 'fulfilled' ? perfil.value : null,
    pedidos: pedidos.status === 'fulfilled' ? pedidos.value : [],
    avisos: avisos.status === 'fulfilled' ? avisos.value : [],
    erros: [perfil, pedidos, avisos]
      .filter((r) => r.status === 'rejected')
      .map((r) => r.reason.message),
  };
}

