function componentes(grafo) {
  const visitado = new Set();
  function dfs(v) {
    visitado.add(v);
    for (const viz of grafo.get(v) || []) if (!visitado.has(viz)) dfs(viz);
  }
  let total = 0;
  for (const v of grafo.keys()) {
    if (!visitado.has(v)) { total++; dfs(v); }
  }
  return total;
}

