function fibLento(n) {
  if (n < 2) return n;
  return fibLento(n - 1) + fibLento(n - 2);
}

function fib(n, memo = new Map()) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const r = fib(n - 1, memo) + fib(n - 2, memo);
  memo.set(n, r);
  return r;
}

