type Forma =
  | { kind: 'circulo'; raio: number }
  | { kind: 'quadrado'; lado: number }
  | { kind: 'retangulo'; largura: number; altura: number };

function area(f: Forma): number {
  switch (f.kind) {
    case 'circulo':
      return Math.PI * f.raio ** 2;
    case 'quadrado':
