async function comRetry(fn, tentativas) {
  let ultimoErro;
  for (let i = 0; i < tentativas; i++) {
    try {
      return await fn();
    } catch (err) {
      ultimoErro = err;
      if (i < tentativas - 1) {
        await new Promise((r) => setTimeout(r, Math.random() * Math.min(10, 2 ** i)));
      }
    }
  }
  throw ultimoErro;
}

