class Fila {
  constructor() {
    this.itens = [];
    this.inicio = 0;
  }
  enqueue(x) { this.itens.push(x); }
  dequeue() {
    if (this.size === 0) return undefined;
    const x = this.itens[this.inicio];
    this.itens[this.inicio] = undefined;
    this.inicio++;
    return x;
  }
  peek() { return this.size ? this.itens[this.inicio] : undefined; }
  get size() { return this.itens.length - this.inicio; }
}

