function memoizar(fn) {
  const cache = new Map();
  return function (...args) {
    const chave = JSON.stringify(args);
    if (cache.has(chave)) return cache.get(chave);
    const valor = fn.apply(this, args);
    cache.set(chave, valor);
    return valor;
  };
}

